/* Mobile-first responsive design */
:root {
    --primary-color: #007bff;
    --success-color: #28a745;
    --danger-color: #dc3545;
    --warning-color: #ffc107;
    --info-color: #17a2b8;
    --light-color: #f8f9fa;
    --dark-color: #343a40;
}

/* Base styles */
body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    background-color: #f8f9fa;
    line-height: 1.6;
}

/* Hero Header styles */
.hero-header {
    position: relative;
    background-image: url('../images/hero-ape.png');
    background-size: cover;
    background-position: left center;
    background-repeat: no-repeat;
    min-height: 300px;
    margin-bottom: 2rem;
    border-radius: 0 0 1rem 1rem;
    overflow: hidden;
}

/* Removed blue gradient overlay - pure image background */

.hero-content {
    position: relative;
    z-index: 2;
    height: 100%;
    min-height: 300px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding: 2rem;
}

.hero-text {
    text-align: right;
    color: white;
    margin-right: 3rem;
    max-width: 50%;
    text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8);
}

.hero-title {
    font-size: 3.5rem;
    font-weight: bold;
    margin-bottom: 0.5rem;
    text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8);
}

.hero-tagline {
    font-size: 1.2rem;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 1px;
    margin: 0;
    text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.8);
}

/* Glowing yellow pulse animation for Maximum Brain Analysis */
.maximum-brain-option {
    position: relative;
    padding: 12px 12px 12px 40px; /* Increased left padding for checkbox */
    border-radius: 8px;
    transition: all 0.3s ease;
}

.maximum-brain-option::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(255, 193, 7, 0.15);
    border-radius: 8px;
    animation: yellowPulse 3s ease-in-out infinite;
    pointer-events: none;
}

/* Ensure checkbox is positioned within the glow area */
.maximum-brain-option .form-check-input {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    margin: 0;
}

.maximum-brain-option .form-check-label {
    padding-left: 0;
    margin-left: 0;
}

@keyframes yellowPulse {
    0%, 100% {
        box-shadow: 0 0 0 0 rgba(255, 193, 7, 0.4);
        background: rgba(255, 193, 7, 0.1);
    }
    50% {
        box-shadow: 0 0 20px 8px rgba(255, 193, 7, 0.2);
        background: rgba(255, 193, 7, 0.2);
    }
}

.maximum-brain-option:hover::before {
    animation-duration: 1.5s;
    box-shadow: 0 0 25px 10px rgba(255, 193, 7, 0.3);
}

/* Income-focused analysis styling */
.income-focus-option {
    position: relative;
    padding: 12px 12px 12px 40px;
    border-radius: 8px;
    transition: all 0.3s ease;
    background: rgba(23, 162, 184, 0.05);
    border: 1px solid rgba(23, 162, 184, 0.1);
}

.income-focus-option:hover {
    background: rgba(23, 162, 184, 0.1);
    border-color: rgba(23, 162, 184, 0.2);
}

.income-focus-option .form-check-input {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    margin: 0;
}

.income-focus-option .form-check-label {
    padding-left: 0;
    margin-left: 0;
}

/* Responsive hero header */
@media (max-width: 768px) {
    .hero-header {
        min-height: 200px;
        background-position: center left;
    }

    .hero-content {
        min-height: 200px;
        justify-content: flex-end;
        padding: 1rem;
    }

    .hero-text {
        margin-right: 2rem;
        text-align: right;
        max-width: 60%;
    }

    .hero-title {
        font-size: 2rem;
    }

    .hero-tagline {
        font-size: 0.85rem;
    }
}

@media (max-width: 480px) {
    .hero-header {
        min-height: 160px;
    }

    .hero-content {
        min-height: 160px;
        justify-content: flex-end;
    }

    .hero-text {
        margin-right: 1rem;
        max-width: 55%;
        text-align: right;
    }

    .hero-title {
        font-size: 1.75rem;
    }

