}

/* Card enhancements */
.card {
    border-radius: 1rem;
    transition: all 0.3s ease;
}

.card:hover {
    transform: translateY(-2px);
}

.card-body {
    padding: 1.5rem;
}

/* Form styles */
.form-control {
    border-radius: 0.5rem;
    border: 2px solid #e9ecef;
